-- BEGIN UNNIE-164 SEOUL DEMO ADDITIONS
-- 서울 신규 가상 매장 50 / 일반 시술 130 / 초보 시술 20 (16개 매장).
-- 기존 02 및 03의 시연·결제·예약 데이터는 유지한다. 01 스키마와 CATEGORY 1~5가 선행 조건이다.
-- ID는 SEQ_SHOP / SEQ_TREATMENT / SEQ_SHOP_BUSINESS_HOUR / SEQ_SHOP_SCHEDULE_EXCEPTION.NEXTVAL로 발급한다.
-- 앱과 같은 시퀀스를 소비하므로 고정 PK나 시퀀스 재시작 없이 이후 앱 생성과 충돌하지 않는다.
-- 신규 로그인 ID는 demo164_s01~demo164_s50이다. PASSWORD_HASH는 명백한 더미 CHANGE_ME이며 로그인할 수 없다.
-- 실제 자격 증명은 작성하지 않는다. 사장님 로그인·결제 시연은 기존 초기/시연 계정을 사용한다.
-- 주소·좌표는 OpenStreetMap 원본의 공개 주소 지점으로 대조했다. 실제 입점·업체 정보가 아니다.
-- OSM 기여자, ODbL 1.0: https://www.openstreetmap.org/copyright
-- 원본 지점·조회일·출처: docs/demo/164/location-sources/*.json (2026-11-02 확인).
-- 좌표는 지도 시연용 주소 지점이며 측량·출입구 위치 정확도를 보증하지 않는다.
-- 사진은 별도 생성·업로드 후 연결한다. 업로드 전 IMAGE_URL은 NULL이며 없는 경로를 넣지 않는다.
-- local H2는 앱 시작 시 전체 03을 자동 로드한다. Oracle은 수동 실행한다.
-- 신규 블록만 재실행하면 로그인 ID/매장별 시술명/요일/OPEN 시작·종료로 중복을 건너뛴다.
-- 기존 03 본문은 고정 PK를 사용하므로 이미 적용한 DB에 전체 03을 재실행하지 않는다.
-- 기존 DB에는 대상 환경 확인 후 docs/demo/164/demo164-additions.sql만 실행한다.
-- 전용 시연 DB에서 트랜잭션으로 실행하고 집계/FK/필수값 확인 후 사람이 COMMIT한다.
-- 이 파일은 DB에 자동 COMMIT하거나 기존 데이터를 삭제하지 않는다.

-- 1. 다온 강남 네일 스튜디오: 일반 2, 모델 0; OSM node/368621524
INSERT INTO SHOP (SHOP_ID, CATEGORY_ID, LOGIN_ID, PASSWORD_HASH, NAME, REGION_CODE, ADDRESS, ADDRESS_DETAIL,
    LATITUDE, LONGITUDE, PHONE, DESCRIPTION, NOTICE, STATUS, CREATED_AT, UPDATED_AT)
SELECT SEQ_SHOP.NEXTVAL, 1, 'demo164_s01', 'CHANGE_ME', '다온 강남 네일 스튜디오', '11680', '서울특별시 강남구 삼성로 29', '시연용 가상공간',
    37.4871750, 127.0656130, '02-0000-0000', '강남구에서 편안하게 머무는 다온 강남 네일 스튜디오입니다. 취향과 컨디션을 충분히 상담하고 한 분씩 정성껏 관리합니다. 시연을 위해 만든 가상 매장입니다.',
    '시연용 가상 매장입니다. 주소는 지도 시연용이며 실제 입점 정보가 아닙니다. 표시된 전화번호는 연결되지 않는 더미입니다.', 'ACTIVE', TIMESTAMP '2026-11-02 09:00:00', TIMESTAMP '2026-11-02 09:00:00'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM SHOP WHERE LOGIN_ID = 'demo164_s01');
INSERT INTO TREATMENT (TREATMENT_ID, SHOP_ID, NAME, DESCRIPTION, REGULAR_PRICE, PRICE, LAST_MINUTE_PRICE,
    DURATION_MINUTES, TREATMENT_TYPE, MODEL_CONDITION, PREPARATION_NOTES, PHOTO_NOTICE, STATUS, CREATED_AT, UPDATED_AT)
SELECT SEQ_TREATMENT.NEXTVAL, (SELECT SHOP_ID FROM SHOP WHERE LOGIN_ID = 'demo164_s01'), '핑크 시럽 젤네일', '손톱 길이와 모양을 상담하고 큐티클 정리부터 마무리 보습까지 진행합니다. 기존 젤 제거는 예약 전 상담해 주세요.', 47000, 42300, 35900,
    60, 'NORMAL', NULL, '예약 시간 10분 전 도착해 주세요. 기존 시술 이력과 알레르기 등 상담할 내용을 미리 알려 주세요.', NULL, 'ACTIVE', TIMESTAMP '2026-11-02 09:00:00', TIMESTAMP '2026-11-02 09:00:00'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM TREATMENT WHERE SHOP_ID = (SELECT SHOP_ID FROM SHOP WHERE LOGIN_ID = 'demo164_s01') AND NAME = '핑크 시럽 젤네일');
