SELECT SEQ_SHOP.NEXTVAL, 5, 'demo164_s10', 'CHANGE_ME', '여운 마포 메이크업 스튜디오', '11440', '서울특별시 마포구 와우산로 56', '시연용 가상공간',
    37.5494391, 126.9234294, '02-0000-0000', '마포구에서 편안하게 머무는 여운 마포 메이크업 스튜디오입니다. 취향과 컨디션을 충분히 상담하고 한 분씩 정성껏 관리합니다. 시연을 위해 만든 가상 매장입니다.',
