SELECT SEQ_TREATMENT.NEXTVAL, (SELECT SHOP_ID FROM SHOP WHERE LOGIN_ID = 'demo164_s12'), '초콜릿 브라운 전체 염색', '모발 상태와 평소 손질 방법을 살펴 디자인을 상담합니다. 샴푸와 마무리 스타일링을 포함하며 추가 작업은 먼저 안내합니다.', 90000, 90000, 90000,
    120, 'NORMAL', NULL, '예약 시간 10분 전 도착해 주세요. 기존 시술 이력과 알레르기 등 상담할 내용을 미리 알려 주세요.', NULL, 'ACTIVE', TIMESTAMP '2026-11-02 09:00:00', TIMESTAMP '2026-11-02 09:00:00'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM TREATMENT WHERE SHOP_ID = (SELECT SHOP_ID FROM SHOP WHERE LOGIN_ID = 'demo164_s12') AND NAME = '초콜릿 브라운 전체 염색');
