SELECT SEQ_TREATMENT.NEXTVAL, (SELECT SHOP_ID FROM SHOP WHERE LOGIN_ID = 'demo164_s22'), '미디엄 레이어드 커트', '모발 상태와 평소 손질 방법을 살펴 디자인을 상담합니다. 샴푸와 마무리 스타일링을 포함하며 추가 작업은 먼저 안내합니다.', 47000, 42300, 35900,
    60, 'NORMAL', NULL, '예약 시간 10분 전 도착해 주세요. 기존 시술 이력과 알레르기 등 상담할 내용을 미리 알려 주세요.', NULL, 'ACTIVE', TIMESTAMP '2026-11-02 09:00:00', TIMESTAMP '2026-11-02 09:00:00'
