SELECT SEQ_TREATMENT.NEXTVAL, (SELECT SHOP_ID FROM SHOP WHERE LOGIN_ID = 'demo164_s22'), '애쉬 브라운 전체 염색 초보 시술 모델', '초보 시술 모델 모집입니다. 모발 상태와 평소 손질 방법을 살펴 디자인을 상담합니다. 샴푸와 마무리 스타일링을 포함하며 추가 작업은 먼저 안내합니다.', 102000, 40800, 34600,
    150, 'MODEL', '성인 참여자를 모집합니다. 지도 담당자와 함께하는 초보 시술로 시간이 더 걸릴 수 있습니다. 가능한 디자인과 시술 이력을 사전 상담해 주세요.', '예약 시간 10분 전 도착해 주세요. 기존 시술 이력과 알레르기 등 상담할 내용을 미리 알려 주세요.', '상담 후 동의한 범위에서 시술 부위의 전후 사진을 촬영합니다. 얼굴 전체와 성명은 촬영·공개하지 않습니다. 사용 목적과 공개 범위를 먼저 안내합니다.', 'ACTIVE', TIMESTAMP '2026-11-02 09:00:00', TIMESTAMP '2026-11-02 09:00:00'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM TREATMENT WHERE SHOP_ID = (SELECT SHOP_ID FROM SHOP WHERE LOGIN_ID = 'demo164_s22') AND NAME = '애쉬 브라운 전체 염색 초보 시술 모델');
