SELECT SEQ_TREATMENT.NEXTVAL, (SELECT SHOP_ID FROM SHOP WHERE LOGIN_ID = 'demo164_s23'), '내추럴 속눈썹 펌', '눈매와 기존 속눈썹 상태를 확인하고 자연스러운 컬을 상담합니다. 시술 전에는 눈가 화장을 지워 주세요.', 49000, 41600, 35300,
    60, 'NORMAL', NULL, '예약 시간 10분 전 도착해 주세요. 기존 시술 이력과 알레르기 등 상담할 내용을 미리 알려 주세요.', NULL, 'ACTIVE', TIMESTAMP '2026-11-02 09:00:00', TIMESTAMP '2026-11-02 09:00:00'
