SELECT SEQ_SHOP.NEXTVAL, 5, 'demo164_s30', 'CHANGE_ME', '해봄 종로 메이크업 스튜디오', '11110', '서울특별시 종로구 창경궁로 240-15', '시연용 가상공간',
    37.5822042, 126.9991240, '02-0000-0000', '종로구에서 편안하게 머무는 해봄 종로 메이크업 스튜디오입니다. 취향과 컨디션을 충분히 상담하고 한 분씩 정성껏 관리합니다. 시연을 위해 만든 가상 매장입니다.',
    '시연용 가상 매장입니다. 주소는 지도 시연용이며 실제 입점 정보가 아닙니다. 표시된 전화번호는 연결되지 않는 더미입니다.', 'ACTIVE', TIMESTAMP '2026-11-02 09:00:00', TIMESTAMP '2026-11-02 09:00:00'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM SHOP WHERE LOGIN_ID = 'demo164_s30');
