-- 32. 느루 중구 헤어 스튜디오: 일반 2, 모델 0; OSM node/368602582
INSERT INTO SHOP (SHOP_ID, CATEGORY_ID, LOGIN_ID, PASSWORD_HASH, NAME, REGION_CODE, ADDRESS, ADDRESS_DETAIL,
    LATITUDE, LONGITUDE, PHONE, DESCRIPTION, NOTICE, STATUS, CREATED_AT, UPDATED_AT)
SELECT SEQ_SHOP.NEXTVAL, 2, 'demo164_s32', 'CHANGE_ME', '느루 중구 헤어 스튜디오', '11140', '서울특별시 중구 퇴계로6길 3-15', '시연용 가상공간',
    37.5584091, 126.9790175, '02-0000-0000', '중구에서 편안하게 머무는 느루 중구 헤어 스튜디오입니다. 취향과 컨디션을 충분히 상담하고 한 분씩 정성껏 관리합니다. 시연을 위해 만든 가상 매장입니다.',
    '시연용 가상 매장입니다. 주소는 지도 시연용이며 실제 입점 정보가 아닙니다. 표시된 전화번호는 연결되지 않는 더미입니다.', 'ACTIVE', TIMESTAMP '2026-11-02 09:00:00', TIMESTAMP '2026-11-02 09:00:00'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM SHOP WHERE LOGIN_ID = 'demo164_s32');
INSERT INTO TREATMENT (TREATMENT_ID, SHOP_ID, NAME, DESCRIPTION, REGULAR_PRICE, PRICE, LAST_MINUTE_PRICE,
    DURATION_MINUTES, TREATMENT_TYPE, MODEL_CONDITION, PREPARATION_NOTES, PHOTO_NOTICE, STATUS, CREATED_AT, UPDATED_AT)
SELECT SEQ_TREATMENT.NEXTVAL, (SELECT SHOP_ID FROM SHOP WHERE LOGIN_ID = 'demo164_s32'), '미디엄 S컬 펌', '모발 상태와 평소 손질 방법을 살펴 디자인을 상담합니다. 샴푸와 마무리 스타일링을 포함하며 추가 작업은 먼저 안내합니다.', 144000, 122400, 122400,
    150, 'NORMAL', NULL, '예약 시간 10분 전 도착해 주세요. 기존 시술 이력과 알레르기 등 상담할 내용을 미리 알려 주세요.', NULL, 'ACTIVE', TIMESTAMP '2026-11-02 09:00:00', TIMESTAMP '2026-11-02 09:00:00'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM TREATMENT WHERE SHOP_ID = (SELECT SHOP_ID FROM SHOP WHERE LOGIN_ID = 'demo164_s32') AND NAME = '미디엄 S컬 펌');
