    90, 'NORMAL', NULL, '예약 시간 10분 전 도착해 주세요. 기존 시술 이력과 알레르기 등 상담할 내용을 미리 알려 주세요.', NULL, 'ACTIVE', TIMESTAMP '2026-11-02 09:00:00', TIMESTAMP '2026-11-02 09:00:00'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM TREATMENT WHERE SHOP_ID = (SELECT SHOP_ID FROM SHOP WHERE LOGIN_ID = 'demo164_s39') AND NAME = '기본 모공 클렌징');
INSERT INTO TREATMENT (TREATMENT_ID, SHOP_ID, NAME, DESCRIPTION, REGULAR_PRICE, PRICE, LAST_MINUTE_PRICE,
    DURATION_MINUTES, TREATMENT_TYPE, MODEL_CONDITION, PREPARATION_NOTES, PHOTO_NOTICE, STATUS, CREATED_AT, UPDATED_AT)
SELECT SEQ_TREATMENT.NEXTVAL, (SELECT SHOP_ID FROM SHOP WHERE LOGIN_ID = 'demo164_s39'), '유수분 밸런스 관리 초보 시술 모델', '초보 시술 모델 모집입니다. 피부 상태를 상담한 뒤 클렌징과 해당 관리, 보습 마무리를 진행합니다. 자극이 느껴지면 즉시 알려 주세요.', 70000, 28000, 23800,
    90, 'MODEL', '성인 참여자를 모집합니다. 지도 담당자와 함께하는 초보 시술로 시간이 더 걸릴 수 있습니다. 가능한 디자인과 시술 이력을 사전 상담해 주세요.', '예약 시간 10분 전 도착해 주세요. 기존 시술 이력과 알레르기 등 상담할 내용을 미리 알려 주세요.', '상담 후 동의한 범위에서 시술 부위의 전후 사진을 촬영합니다. 얼굴 전체와 성명은 촬영·공개하지 않습니다. 사용 목적과 공개 범위를 먼저 안내합니다.', 'ACTIVE', TIMESTAMP '2026-11-02 09:00:00', TIMESTAMP '2026-11-02 09:00:00'
FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM TREATMENT WHERE SHOP_ID = (SELECT SHOP_ID FROM SHOP WHERE LOGIN_ID = 'demo164_s39') AND NAME = '유수분 밸런스 관리 초보 시술 모델');
