-- 42. 담빛 노원 헤어 스튜디오: 일반 4, 모델 0; OSM node/368741371
INSERT INTO SHOP (SHOP_ID, CATEGORY_ID, LOGIN_ID, PASSWORD_HASH, NAME, REGION_CODE, ADDRESS, ADDRESS_DETAIL,
    LATITUDE, LONGITUDE, PHONE, DESCRIPTION, NOTICE, STATUS, CREATED_AT, UPDATED_AT)
SELECT SEQ_SHOP.NEXTVAL, 2, 'demo164_s42', 'CHANGE_ME', '담빛 노원 헤어 스튜디오', '11350', '서울특별시 노원구 공릉로46길 3', '시연용 가상공간',
    37.6271350, 127.0790134, '02-0000-0000', '노원구에서 편안하게 머무는 담빛 노원 헤어 스튜디오입니다. 취향과 컨디션을 충분히 상담하고 한 분씩 정성껏 관리합니다. 시연을 위해 만든 가상 매장입니다.',
